다음 Java 프로그램의 실행 결과는?

[코드]
class Main {
    static void work(int[] slot) {
        try {
            slot[2] = 5;
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.print("1");
            System.out.print(10 / (slot.length - 2));
        } finally {
            System.out.print("2");
        }
        System.out.print("3");
    }
    public static void main(String[] args) {
        try {
            work(new int[2]);
        } catch (ArithmeticException e) {
            System.out.print("4");
        }
    }
}

