        try {
            System.out.print(8 / stock[i]);
        } catch (ArithmeticException e) {
            System.out.print("A");
        } finally {
            System.out.print("F ");
        }
    }
    public static void main(String[] args) {
        for (int i = 0; i < 3; i++)
            try {
                check(i);
            } catch (Exception e) {
                System.out.print("M");
            }
    }
}

