    try:
        return int(seq[k])
    except IndexError:
        return -1
    except ValueError:
        return -2
    except Exception:
        return -3
s = ["a"]
d = {"n": "8"}
print(pick(s, 0), pick(s, 5), pick(d, "n"), pick(d, "m"))

다음 파이썬(Python) 프로그램의 실행 결과는?

[코드]
def load(n):
    try:
        print("L", end='')
        return [3, 6, 9][n]
    finally:
        print("F", end='')
total = 0
for n in [1, 5, 2]:
    try:
        total += load(n)
    except IndexError:
        print("X", end='')
print("", total)

